from itertools import combinations
n = 21
S = {1,2,3,4,5}
edges = []
for i in range(n):
    for k in S:
        j = (i+k) % n
        u,v = min(i,j), max(i,j)
        edges.append((u,v))
edges = sorted(set(edges))
print(len(edges))

# Verify alpha <= 4
adj = {i:set() for i in range(n)}
for u,v in edges:
    adj[u].add(v); adj[v].add(u)

max_ind = 0
for size in range(4, 6):
    found = False
    for combo in combinations(range(n), size):
        ok = all(b not in adj[a] for a,b in combinations(combo,2))
        if ok:
            found = True; print("ind set size",size,combo); break
    print(f"size {size} independent exists:", found)

# Verify connectivity >= 4 via networkx
try:
    import networkx as nx
    G = nx.Graph(); G.add_edges_from(edges)
    print("connectivity:", nx.node_connectivity(G))
except Exception as e:
    print(e)
print(edges)
